import{_ as t,o as a,c as i,a4 as o}from"./chunks/framework.BFhWjAjl.js";const u=JSON.parse('{"title":"Troubleshooting and performance","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md","lastUpdated":null}'),s={name:"troubleshooting.md"};function r(d,e,n,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="Troubleshooting-and-performance" tabindex="-1">Troubleshooting and performance <a class="header-anchor" href="#Troubleshooting-and-performance" aria-label="Permalink to &quot;Troubleshooting and performance {#Troubleshooting-and-performance}&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:right;">Symptom</th><th style="text-align:right;">Likely cause and action</th></tr></thead><tbody><tr><td style="text-align:right;"><code>Pkg.add(&quot;MetricSpaces&quot;)</code> cannot resolve</td><td style="text-align:right;">Use a source checkout with <code>Pkg.develop(path=...)</code> or the repository URL; see <a href="/MetricSpaces.jl/dev/getting_started#Getting-Started">Getting Started</a>.</td></tr><tr><td style="text-align:right;"><code>sphere</code> or <code>torus</code> is undefined</td><td style="text-align:right;">Import <code>MetricSpaces.Datasets</code> or individual generators from it.</td></tr><tr><td style="text-align:right;"><code>pairwise_distance(X)</code> has no method</td><td style="text-align:right;">Pass both clouds and a distance: <code>pairwise_distance(X, X, dist_euclidean)</code>.</td></tr><tr><td style="text-align:right;">A matrix becomes a cloud with the wrong number of points</td><td style="text-align:right;">Matrices use columns as observations; transpose row-oriented data.</td></tr><tr><td style="text-align:right;">A query vector has a dispatch error</td><td style="text-align:right;">Match the query to the cloud&#39;s element type; use <code>typeof(X[1])(coordinates)</code> for fixed-size points.</td></tr><tr><td style="text-align:right;"><code>X[random_sample(X, n)]</code> fails</td><td style="text-align:right;"><code>random_sample</code> returns points. Select indices explicitly with <code>randperm</code> when needed.</td></tr><tr><td style="text-align:right;">A density score is <code>Inf</code></td><td style="text-align:right;">Self-neighbors or duplicates give zero radius. Increase <code>k</code> and inspect duplicates.</td></tr><tr><td style="text-align:right;">Geodesic distances are <code>Inf</code></td><td style="text-align:right;">The k-neighbor graph is disconnected. Inspect components and assess whether a larger <code>k</code> is appropriate.</td></tr><tr><td style="text-align:right;">Radius changes appear ineffective</td><td style="text-align:right;">Distances, standardization, and open versus closed boundaries can change expectations; inspect individual distances.</td></tr><tr><td style="text-align:right;">Memory grows rapidly</td><td style="text-align:right;">Dense pairwise/geodesic matrices need quadratic memory; use summaries or landmarks when possible.</td></tr></tbody></table><h2 id="Threaded-execution" tabindex="-1">Threaded execution <a class="header-anchor" href="#Threaded-execution" aria-label="Permalink to &quot;Threaded execution {#Threaded-execution}&quot;">​</a></h2><p>Start Julia with <code>--threads=auto</code> to enable parallel work. The distance callable can run concurrently; avoid callbacks that mutate shared state. Threading does not change the quadratic number of comparisons, and tiny examples can be faster on one thread. Time repeated runs after compilation before attributing startup cost to an algorithm.</p><h2 id="Reproduce-a-result" tabindex="-1">Reproduce a result <a class="header-anchor" href="#Reproduce-a-result" aria-label="Permalink to &quot;Reproduce a result {#Reproduce-a-result}&quot;">​</a></h2><p>Keep the project and manifest, Julia version, observation ordering, distance definition, and RNG seed. An ε-net depends on input order; farthest-point sampling depends on random initialization and tie order. Index covers always refer to the cloud used to create them; rebuild covers after filtering or reordering data.</p><h2 id="Build-this-documentation-locally" tabindex="-1">Build this documentation locally <a class="header-anchor" href="#Build-this-documentation-locally" aria-label="Permalink to &quot;Build this documentation locally {#Build-this-documentation-locally}&quot;">​</a></h2><p>From the package directory, prepare its documentation environment:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/setup.jl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=docs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/make.jl</span></span></code></pre></div><p>Then run <code>julia --project=docs docs/make.jl</code> from a terminal. The setup script resolves source paths relative to its own location and refreshes a stale docs manifest. The Documenter examples use small local datasets. The configured VitePress renderer also needs its Node/npm build dependencies. Deployment is handled by repository CI; a local build does not need publishing credentials.</p>`,10)])])}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
